  var LANGS = [["tr", "Türkçe", "TR"], ["en", "English", "EN"], ["es", "Español", "ES"], ["de", "Deutsch", "DE"], ["ru", "Русский", "RU"], ["zh", "中文", "中文"]];
  var LI = { es: 0, de: 1, ru: 2, zh: 3 };
  function out(en){ if (lang === "en" || !(lang in LI)) return en; var r = X[en]; return r ? (r[LI[lang]] === "∅" ? "" : r[LI[lang]]) : en; }
  var KEYS = Object.keys(D).sort(function(a, b){ return b.length - a.length; });
