    var t = s.trim(); if (!t || !/\p{L}/u.test(t)) return s;
    var lead = s.slice(0, s.indexOf(t)), tail = s.slice(s.indexOf(t) + t.length);
    if (Object.prototype.hasOwnProperty.call(D, t)) return lead + out(D[t]) + tail;
    for (var i = 0; i < P.length; i++) { var m = t.match(P[i][0]); if (m) { var rec = P[i][2]; return lead + out(P[i][1]).replace(/\{(\d)\}/g, function(z, d){ return rec ? tr(m[d]) : m[d]; }) + tail; } }
