  /* Dil düğmesi: her ekranın başlığına (ya da giriş kartına) yerleşir; dokununca dil listesi açılır */
  var GLOBE = '<svg viewBox="0 0 24 24" width="15" height="15" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" aria-hidden="true"><circle cx="12" cy="12" r="9"/><path d="M3 12h18M12 3a14 14 0 0 1 0 18M12 3a14 14 0 0 0 0 18"/></svg>';
  function cur(){ return LANGS.filter(function(l){ return l[0] === lang; })[0]; }
