  function makeBtn(){
    var b = document.createElement("button"); b.type = "button"; b.className = "lang-btn"; b.setAttribute("data-no-i18n", "");
    b.setAttribute("aria-haspopup", "true"); b.setAttribute("aria-label", "Dil · Language"); b.innerHTML = btnHtml(); return b;
  }
