    m.className = "lang-menu"; m.setAttribute("role", "menu"); m.setAttribute("data-no-i18n", "");
    m.innerHTML = LANGS.map(function(l){ return '<button type="button" role="menuitemradio" aria-checked="' + (l[0] === lang) + '" data-lang="' + l[0] + '"><b>' + l[2] + '</b>' + l[1] + '</button>'; }).join("");
    document.body.appendChild(m);
    var w = m.offsetWidth, h = m.offsetHeight, left = Math.min(Math.max(8, r.right - w), window.innerWidth - w - 8), top = r.bottom + 6;
